+      case VELAPOKA_STATE_FAIL:
+        return next == VELAPOKA_STATE_CAPTURE ||
+               next == VELAPOKA_STATE_SAMPLE_CAPTURE;
+      case VELAPOKA_STATE_CAPTURE:
+        return next == VELAPOKA_STATE_PREPROCESS;
+      case VELAPOKA_STATE_PREPROCESS:
