+
+int velapoka_state_transition(FAR struct velapoka_state_s *state,
+                              enum velapoka_state_e next)
+{
+  FAR const char *before;
+  FAR const char *after;
+
+  if (state == NULL || next > VELAPOKA_STATE_ERROR)
+    {
+      return -EINVAL;
