   243	static void velapoka_inspect_run(FAR struct velapoka_inspector_s *inspector,
   244	                                 FAR struct velapoka_result_s *result)
   245	{
   246	  bool abnormal[VELAPOKA_BLOCK_COUNT];
   247	  struct timespec started;
   248	  struct timespec finished;
   249	  uint64_t reference_sum = 0;
   250	  uint64_t current_sum = 0;
   251	  uint32_t gain_q12;
   252	  unsigned int abnormal_count = 0;
   253	  unsigned int largest_blocks;
   254	  unsigned int block_x;
   255	  unsigned int block_y;
   256	  unsigned int x;
   257	  unsigned int y;
   258	
   259	  clock_gettime(CLOCK_MONOTONIC, &started);
   260	  memset(result, 0, sizeof(*result));
   261	  result->sequence = inspector->sequence;
   262	
   263	  for (y = VELAPOKA_ROI_Y;
   264	       y < VELAPOKA_ROI_Y + VELAPOKA_ROI_HEIGHT; y++)
   265	    {
   266	      for (x = VELAPOKA_ROI_X;
   267	           x < VELAPOKA_ROI_X + VELAPOKA_ROI_WIDTH; x++)
   268	        {
   269	          unsigned int offset = y * VELAPOKA_INSPECT_WIDTH + x;
   270	          reference_sum += inspector->reference[offset];
   271	          current_sum += inspector->current[offset];
   272	        }
   273	    }
   274	
   275	  if (current_sum == 0)
   276	    {
   277	      current_sum = 1;
   278	    }
   279	
   280	  gain_q12 = (reference_sum << 12) / current_sum;
   281	  if (gain_q12 > (8 << 12))
   282	    {
   283	      gain_q12 = 8 << 12;
   284	    }
   285	
   286	  for (y = 0; y < VELAPOKA_INSPECT_HEIGHT; y++)
   287	    {
   288	      for (x = 0; x < VELAPOKA_INSPECT_WIDTH; x++)
   289	        {
   290	          unsigned int offset = y * VELAPOKA_INSPECT_WIDTH + x;
   291	          uint32_t value = ((uint32_t)inspector->current[offset] *
   292	                            gain_q12 + (1 << 11)) >> 12;
   293	          inspector->normalized[offset] =
   294	            value > UINT8_MAX ? UINT8_MAX : (uint8_t)value;
   295	        }
   296	    }
   297	
   298	  for (block_y = 0; block_y < VELAPOKA_BLOCK_ROWS; block_y++)
   299	    {
   300	      for (block_x = 0; block_x < VELAPOKA_BLOCK_COLUMNS; block_x++)
   301	        {
   302	          uint32_t absolute_sum = 0;
   303	          uint32_t edge_sum = 0;
   304	          uint32_t pixels = 0;
   305	          uint32_t edge_pixels = 0;
   306	          uint32_t metric;
   307	          unsigned int start_x = VELAPOKA_ROI_X +
   308	                                 block_x * VELAPOKA_INSPECT_BLOCK_SIZE;
   309	          unsigned int start_y = VELAPOKA_ROI_Y +
   310	                                 block_y * VELAPOKA_INSPECT_BLOCK_SIZE;
   311	          unsigned int index = block_y * VELAPOKA_BLOCK_COLUMNS + block_x;
   312	
   313	          for (y = start_y;
   314	               y < start_y + VELAPOKA_INSPECT_BLOCK_SIZE; y++)
   315	            {
   316	              for (x = start_x;
   317	                   x < start_x + VELAPOKA_INSPECT_BLOCK_SIZE; x++)
   318	                {
   319	                  unsigned int offset = y * VELAPOKA_INSPECT_WIDTH + x;
   320	                  int difference = inspector->normalized[offset] -
   321	                                   inspector->reference[offset];
   322	
   323	                  absolute_sum += abs(difference);
   324	                  pixels++;
   325	                  if (x + 1 < start_x + VELAPOKA_INSPECT_BLOCK_SIZE &&
   326	                      y + 1 < start_y + VELAPOKA_INSPECT_BLOCK_SIZE)
   327	                    {
   328	                      unsigned int right = offset + 1;
   329	                      unsigned int down = offset + VELAPOKA_INSPECT_WIDTH;
   330	                      int current_edge =
   331	                        abs(inspector->normalized[right] -
   332	                            inspector->normalized[offset]) +
   333	                        abs(inspector->normalized[down] -
   334	                            inspector->normalized[offset]);
   335	                      int reference_edge =
   336	                        abs(inspector->reference[right] -
   337	                            inspector->reference[offset]) +
   338	                        abs(inspector->reference[down] -
   339	                            inspector->reference[offset]);
   340	
   341	                      edge_sum += abs(current_edge - reference_edge) / 2;
   342	                      edge_pixels++;
   343	                    }
   344	                }
   345	            }
   346	
   347	          metric = (3 * (absolute_sum / pixels) +
   348	                    (edge_pixels > 0 ? edge_sum / edge_pixels : 0)) / 4;
   349	          abnormal[index] = metric * 100 >=
   350	                            VELAPOKA_BLOCK_DIFF_PERCENT * UINT8_MAX;
   351	          if (abnormal[index])
   352	            {
   353	              abnormal_count++;
   354	            }
   355	        }
   356	    }
   357	
   358	  result->difference_tenths = abnormal_count * 1000 /
   359	                              VELAPOKA_BLOCK_COUNT;
   360	  result->score_tenths = 1000 - result->difference_tenths;
   361	  velapoka_find_components(abnormal, result, &largest_blocks);
   362	  result->pass = result->difference_tenths <=
   363	                   inspector->threshold_percent * 10 &&
   364	                 largest_blocks * 1000 / VELAPOKA_BLOCK_COUNT <=
   365	                   inspector->threshold_percent * 5;
   366	
   367	  clock_gettime(CLOCK_MONOTONIC, &finished);
   368	  result->elapsed_ms = velapoka_elapsed_ms(&started, &finished);
   369	}
